SELECT 'gongkao', '经济利润问题', 'kp-xc-quantity-math-operation-profit', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "经济利润问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "经济利润问题围绕利润、成本、售价、利润率四个量展开，核心公式必须熟练，打折促销是常考场景。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：利润 = 售价 - 成本，利润率 = 利润/成本 × 100%"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "售价 = 成本 × (1 + 利润率)，成本 = 售价 / (1 + 利润率)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "打折：实际售价 = 标价 × 折扣率（如八折 = 0.8）"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分段计价：不同数量区间单价不同，如阶梯电价、阶梯水费"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盈亏平衡：总收入 = 总成本时的销量或单价"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设成本或售价为未知量，用利润率公式列方程"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "打折题先算标价，再乘折扣率得到实际售价"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分段计价题分段计算，注意每段的边界值"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "多件组合题用总价减去单件价格之和算优惠"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "利润率的分母是成本不是售价，这是最常见的错误"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "打折和利润率的关系搞混：八折不等于利润率20%"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分段计价时边界值算错，如\"超过100件\"是>100还是≥100"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "经济利润问题公式性强，练熟公式就能拿分。重点练习打折促销和分段计价两种题型。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数学运算-经济利润问题的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数学运算", "经济利润问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_profit", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
